update public.grapes set summary = 'A red grape grown mainly in Austria and the Czech Republic and closely related to Pinot Noir. It gives wines with cherry fruit and soft tannins.', updated_at = now() where id = '32a7c30a-2a37-4fc5-a0dc-cdbac794bddd';
update public.grapes set summary = 'Thin skinned and fussy, at its best where it''s cool. Pale in the glass, but it carries a lot of scent.', updated_at = now() where id = '04f9fc43-bd96-4579-898e-e93edb225fb4';
update public.grapes set summary = 'Thick skinned, giving deep colour, firm tannins and a long life; it gives Bordeaux blends their backbone.', updated_at = now() where id = '9bd2696f-ce20-4088-bd67-e66be62860cd';
update public.grapes set summary = 'Spain''s flagship red grape: medium to full bodied, with firm tannins, and it takes well to oak.', updated_at = now() where id = '83197ae8-3428-48ef-87df-57d97d2504ee';
update public.grapes set summary = 'The signature red of Bairrada, a small, thick skinned grape giving deeply coloured, tannic reds with high acidity that can be tough young and soften with age.', updated_at = now() where id = '46658579-8c28-484a-bc5e-dce5d769cbeb';
update public.grapes set summary = 'The leading white grape of Portugal''s Alentejo, giving firm, full bodied whites with ripe tropical fruit, tangerine peel and a mineral note.', updated_at = now() where id = 'a59786bf-427d-4076-a463-775e489bfe19';
update public.grapes set summary = 'Loves heat; gives ripe, full reds high in alcohol, most often in a blend, as in the southern Rhône.', updated_at = now() where id = 'aa801da7-4e97-479a-b6ae-5e2f441f4cf5';
update public.grapes set summary = 'Dark fruited and spicy: leaner and more savoury in the northern Rhône, riper and bolder as Shiraz in warm places like Australia.', updated_at = now() where id = '3ca91e07-20f0-4993-9b78-a3061bc1ba77';
update public.grapes set summary = 'Versatile: dry, off dry, sweet or sparkling, always with fresh acidity.', updated_at = now() where id = 'a8ed51cf-28eb-4fb8-b930-2b74aff56c23';
update public.grapes set summary = 'Portugal''s best known red grape: dark, floral and firmly structured, a key grape in port and in dry Douro reds.', updated_at = now() where id = '61c15a2d-6f5f-488d-8250-75b78b55be73';
update public.grapes set summary = 'A disease resistant white from Freiburg with Riesling in its family tree: fruity and fairly full, close to Riesling but with softer acidity.', updated_at = now() where id = '0b8b8b43-6367-4baf-9b37-0d59dfeffbb8';
update public.grapes set summary = 'A disease resistant white bred in Freiburg, with pink skinned berries: often fresh and close to Sauvignon in style, sometimes rounder and fuller.', updated_at = now() where id = '897bba5e-d417-4f92-bf43-07dc637354a0';
update public.grapes set summary = 'One of the first disease resistant grapes planted widely, bred in Germany in 1967: deep in colour and full, with noticeable tannin.', updated_at = now() where id = 'aa37c4ad-fa15-4c72-99ee-8c156b11f5b9';
update public.grapes set summary = 'Italy''s most planted red, at the heart of Tuscany''s wines: cherry fruited and savoury, with high acidity and firm tannins.', updated_at = now() where id = 'e93935bf-2a97-4db3-b9e6-a1194a412956';
update public.grapes set summary = 'Aromatic and high in acidity, at home in cool climates; made in every style from bone dry to lusciously sweet.', updated_at = now() where id = '911bcfd2-1131-435d-a33e-bfa049289138';
update public.grapes set summary = 'A gentle, low acid white, a full sibling of Chardonnay, often blended with Pinot Blanc and at home in Alsace and Luxembourg: round and mild.', updated_at = now() where id = '0f9ca19c-b7a7-47c1-b16b-df0a2b420176';
update public.grapes set summary = 'A disease resistant red bred in Freiburg from Cabernet Sauvignon and Solaris: deep in colour, herbal and spicy, with firm tannins.', updated_at = now() where id = '7aebad49-19a0-42b0-9c0b-81d1ee077306';
update public.grapes set summary = 'A disease resistant red sold as a Pinot Noir type, though DNA points to Cabernet Sauvignon and Regent as parents: soft, with dark fruit.', updated_at = now() where id = '6fd9e7d7-203f-47ca-8473-904dfd37069d';
update public.grapes set summary = 'A disease resistant white bred from Cabernet Sauvignon, with aromas often likened to Sauvignon Blanc.', updated_at = now() where id = '69db4447-077d-46fe-ad17-5074367e6c10';
update public.grapes set summary = 'A grape from south west France that found its home in Argentina: deep purple, plush, with soft tannins.', updated_at = now() where id = 'a305c2c3-2da4-454f-9e61-d7e12eba8833';
update public.grapes set summary = 'Once a Bordeaux grape, rediscovered in Chile in the 1990s, where it had been mistaken for Merlot: soft, with a green pepper edge.', updated_at = now() where id = '8add4129-741e-469f-b77d-ee4c6d7e7287';
update public.grapes set summary = 'A late ripening white grape, known as Esgana Cão on the mainland, that makes the driest style of Madeira, with very high acidity.', updated_at = now() where id = 'c515bd50-8376-4057-afd8-6de7c60f6ac3';
update public.grapes set summary = 'Red grape of north west Spain, mainly Bierzo, Ribeira Sacra and Valdeorras, called Jaen in Portugal. It makes fragrant, medium bodied reds.', updated_at = now() where id = '16a2f7f6-795d-42ac-a61a-d77ba67b5ece';
update public.grapes set summary = 'Georgia''s most planted dark grape, a teinturier with red flesh. It gives deeply coloured reds, dry or semi sweet, with high acidity and firm tannin.', updated_at = now() where id = '7000af60-9f7c-4f7f-a20c-d2b7a672c0c7';
